  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 1, 'Identificar movimento uniforme em registros', 'Reconhecer movimento uniforme comparando deslocamentos em intervalos iguais e distinguindo posição de velocidade. A explicação usa dados explícitos e distingue o modelo físico de conclusões que os dados não autorizam.', '## O critério é a velocidade constante
Em movimento uniforme, a velocidade permanece constante: em intervalos iguais de tempo, o deslocamento é igual. A razão Δposição/Δtempo tem o mesmo valor em cada trecho.

## Posição não é velocidade
Posição constante descreve repouso, um caso particular de movimento uniforme com velocidade zero. Uma posição que cresce ou diminui linearmente pode representar movimento uniforme; o sinal mostra o sentido no eixo escolhido.

## Leia tabelas e gráficos com cuidado
Compare cada par de medidas, não apenas o primeiro e o último valor. Em um gráfico posição-tempo, uma reta com inclinação constante indica velocidade constante; uma reta horizontal indica repouso. Intervalos de tempo iguais, por si só, não garantem movimento uniforme: as variações de posição também precisam ser iguais.',
    'As posições são 0 m, 10 m, 20 m e 30 m nos tempos 0 s, 2 s, 4 s e 6 s. Cada intervalo tem Δposição = 10 m e Δtempo = 2 s; logo v = 5 m/s constante.', array['Anote dados e unidades antes de calcular.', 'Declare o referencial ou o eixo adotado.', 'Mostre a relação usada e confira se a conclusão responde ao enunciado.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-physics-uniform-motion-sequence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler tabelas de valores.","Calcular diferenças e razões simples."],"key_concepts":["posição","deslocamento","velocidade constante","intervalos iguais","inclinação"],"progression":[{"stage":"DIAGNOSTIC","focus":"Verificar ideias iniciais e leitura das grandezas.","questionIds":["v5-physics-uniform-motion-01","v5-physics-uniform-motion-02","v5-physics-uniform-motion-03","v5-physics-uniform-motion-04"]},{"stage":"PRACTICE","focus":"Aplicar o critério com apoio gradual.","questionIds":["v5-physics-uniform-motion-05","v5-physics-uniform-motion-06","v5-physics-uniform-motion-07","v5-physics-uniform-motion-08","v5-physics-uniform-motion-09","v5-physics-uniform-motion-10","v5-physics-uniform-motion-11","v5-physics-uniform-motion-12","v5-physics-uniform-motion-13","v5-physics-uniform-motion-14","v5-physics-uniform-motion-15","v5-physics-uniform-motion-16"]},{"stage":"TRANSFER","focus":"Interpretar dados em contextos e justificar a escolha do modelo.","questionIds":["v5-physics-uniform-motion-17","v5-physics-uniform-motion-18","v5-physics-uniform-motion-19","v5-physics-uniform-motion-20","v5-physics-uniform-motion-21","v5-physics-uniform-motion-22","v5-physics-uniform-motion-23","v5-physics-uniform-motion-24"]},{"stage":"CONSOLIDATION","focus":"Localizar e corrigir erros de raciocínio.","questionIds":["v5-physics-uniform-motion-25","v5-physics-uniform-motion-26","v5-physics-uniform-motion-27","v5-physics-uniform-motion-28","v5-physics-uniform-motion-29","v5-physics-uniform-motion-30"]},{"stage":"REVIEW","focus":"Retomar conceitos com dados e representações variadas.","questionIds":["v5-physics-uniform-motion-31","v5-physics-uniform-motion-32","v5-physics-uniform-motion-33","v5-physics-uniform-motion-34","v5-physics-uniform-motion-35","v5-physics-uniform-motion-36","v5-physics-uniform-motion-37","v5-physics-uniform-motion-38","v5-physics-uniform-motion-39","v5-physics-uniform-motion-40"]}],"micro_explanations":[{"trigger":"COMPARE_INTERVALS","text":"Compare deslocamentos em intervalos iguais, não só posições finais."},{"trigger":"CONSTANT_RATIO","text":"Movimento uniforme mantém Δposição/Δtempo constante."},{"trigger":"REST_IS_ZERO","text":"Posição constante é repouso: velocidade uniforme igual a zero."},{"trigger":"SLOPE_POSITION_TIME","text":"A inclinação de posição-tempo representa velocidade."},{"trigger":"SIGNED_DIRECTION","text":"Inclinação negativa indica movimento no sentido negativo do eixo escolhido."},{"trigger":"EQUAL_TIME_NOT_ENOUGH","text":"Tempos igualmente espaçados não bastam; verifique as mudanças de posição."}],"remediations":[{"id":"SUBTRACT_EACH_STEP","misconception":"Usar apenas o deslocamento total.","prompt":"Calcule posição final menos inicial em cada intervalo e compare as razões."},{"id":"REST_VS_UNIFORM","misconception":"Achar que velocidade constante exige posição constante.","prompt":"Separe posição de velocidade: uma reta inclinada pode ter velocidade constante; horizontal é repouso."},{"id":"EQUAL_INTERVALS","misconception":"Confundir intervalos iguais com movimento uniforme.","prompt":"Compare também os deslocamentos correspondentes a cada intervalo."},{"id":"SIGNED_SLOPE","misconception":"Ignorar movimento no sentido negativo.","prompt":"Mantenha o sinal do deslocamento e interprete-o em relação ao eixo."},{"id":"RATIO_NOT_POSITION","misconception":"Dividir posição final pelo tempo total